#include <iostream>
using namespace std;

// A function of our own: it takes nothing in and hands nothing back.
void printBanner() {
    cout << "=========================" << endl;
    cout << "   POCKET LAB REPORT" << endl;
    cout << "=========================" << endl;
}

int main() {
    cout << "Starting up." << endl;
    printBanner();
    cout << "Doing some work." << endl;
    printBanner();
    cout << "Finished." << endl;
    return 0;
}

